public class METCBCTCustomerSiteOffRemitCostCentreLink extends common
{
}

Method.Source:
    /// <summary>
    /// Find method
    /// </summary>
    /// <param name = "_inventSiteId">Site</param>
    /// <param name = "_forupdate">Select record for update</param>
    /// <param name = "_concurrencyModel">Concurrency model</param>
    /// <returns>The <c>METCBCTCustomerSiteOffRemitCostCentreLink</c> record if found; otherwise, null.</returns>
    public static METCBCTCustomerSiteOffRemitCostCentreLink find(
        InventSiteId            _inventSiteId,
        boolean                 _forupdate        = false,
        ConcurrencyModel        _concurrencyModel = ConcurrencyModel::Auto)
    {
        METCBCTCustomerSiteOffRemitCostCentreLink customerSiteOffRemitCostCentreLink;

        customerSiteOffRemitCostCentreLink.selectForUpdate(_forupdate);
        if (_forupdate  && _concurrencyModel != ConcurrencyModel::Auto)
        {
            customerSiteOffRemitCostCentreLink.concurrencyModel(_concurrencyModel);
        }

        if (_inventSiteId != '')
        {
            select firstonly customerSiteOffRemitCostCentreLink
                where customerSiteOffRemitCostCentreLink.InventSiteId == _inventSiteId;
        }

        return customerSiteOffRemitCostCentreLink;
    }

/// <summary>
/// Exist method
/// </summary>
/// <param name = "_inventSiteId">Site</param>
/// <returns>True if the record exists; otherwise, false.</returns>
public static boolean exist(InventSiteId _inventSiteId)
{
    return (select firstonly
                 RecId
            from
                 METCBCTCustomerSiteOffRemitCostCentreLink
             where
                 METCBCTCustomerSiteOffRemitCostCentreLink.InventSiteId == _inventSiteId).RecId != 0;
}

/// <summary>
/// Cost centre lookup
/// </summary>
/// <param name = "_formStringControl">Form string control</param>
public static void lookupCostCentre(FormStringControl _formStringControl)
{
    DimensionValueLookupHelper::lookupDimensionValues(DimensionAttribute::findByName(METConstants::costCenter), _formStringControl);
}
